"""Custom CUDA top-k kernel for RTX PRO 6000 (SM120).

Three-stage design (no forbidden torch reduction/sort ops are used anywhere):
  K1 seg_topk_kernel:   grid = (batch * S) blocks. Each block owns a
        contiguous segment of a row. Every thread scans elements coalesced
        (stride = block size) and maintains a descending-sorted local top-k
        via insertion (amortized cheap for random data: an element only
        shifts the array when it beats the thread's k-th best). Threads
        write their k candidates to a global staging buffer.
  K2 merge_groups_kernel (pass 1): one block per segment; merges the nth
        per-thread candidate lists (nth*k <= 2048 entries) in shared memory
        into the segment's exact top-k via k rounds of parallel argmax.
  K3 merge_groups_kernel (pass 2): one block per row; merges the S segment
        top-k lists (S*k <= 4096 entries) the same way, producing the
        final row top-k, exactly sorted descending.

S is chosen per shape on the host so total K1 blocks are ~1024 while keeping
S*k <= 4096 for the final merge's shared-memory footprint. k rounds of
parallel argmax is a tree reduction, not a network sort, so non-power-of-two
n needs no special padding.
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

OP_TYPE = "topk"
SUPPORTED_PRECISIONS = ["fp32"]
HARDWARE_REQUIRED = ["RTX_PRO_6000", "H100", "B200"]

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>
#include <ATen/cuda/CUDAContext.h>

#define KMAX 64

// K1: per-thread sorted local top-k of a row segment.
__global__ void seg_topk_kernel(const float* __restrict__ x,
                                float* __restrict__ gval,
                                int* __restrict__ gidx,
                                int n, int k, int S, int seglen) {
    int row = blockIdx.x / S;
    int seg = blockIdx.x - row * S;
    const float* xrow = x + (long long)row * (long long)n;
    long long base = (long long)seg * seglen;
    long long end = base + seglen;
    if (end > n) end = n;

    int tid = threadIdx.x;
    int nth = blockDim.x;

    float v[KMAX];
    int id[KMAX];
#pragma unroll
    for (int i = 0; i < KMAX; ++i) { v[i] = -INFINITY; id[i] = 0; }
    int cnt = 0;

    for (long long i = base + tid; i < end; i += nth) {
        float xv = xrow[i];
        if (cnt < k) {
            int p = cnt;
            while (p > 0 && v[p - 1] < xv) { v[p] = v[p - 1]; id[p] = id[p - 1]; --p; }
            v[p] = xv; id[p] = (int)i; ++cnt;
        } else if (xv > v[k - 1]) {
            int p = k - 1;
            while (p > 0 && v[p - 1] < xv) { v[p] = v[p - 1]; id[p] = id[p - 1]; --p; }
            v[p] = xv; id[p] = (int)i;
        }
    }

    long long out = ((long long)blockIdx.x * nth + tid) * (long long)k;
    float* gv = gval + out;
    int* gi = gidx + out;
    for (int i = 0; i < k; ++i) { gv[i] = v[i]; gi[i] = id[i]; }
}

// K2/K3: one block (128 threads) per output group. Input is `G` consecutive
// groups, each holding k descending-sorted candidates; output is their
// merged top-k, k rounds of parallel argmax over shared-memory candidates.
template <typename IdxT>
__global__ void merge_groups_kernel(const float* __restrict__ gval,
                                    const int* __restrict__ gidx,
                                    float* __restrict__ ovals,
                                    IdxT* __restrict__ oidx,
                                    int k, int G) {
    extern __shared__ float sv[];
    int C = G * k;
    int* si = (int*)(sv + C);
    int nth = blockDim.x;
    long long base = (long long)blockIdx.x * C;

    for (int i = threadIdx.x; i < C; i += nth) {
        sv[i] = gval[base + i];
        si[i] = gidx[base + i];
    }
    __syncthreads();

    __shared__ float tv[128];
    __shared__ int tp[128];

    float* ov = ovals + (long long)blockIdx.x * k;
    IdxT* oi = oidx + (long long)blockIdx.x * k;

    for (int r = 0; r < k; ++r) {
        float best = -INFINITY;
        int pos = 0;
        for (int i = threadIdx.x; i < C; i += nth) {
            if (sv[i] > best) { best = sv[i]; pos = i; }
        }
        tv[threadIdx.x] = best;
        tp[threadIdx.x] = pos;
        __syncthreads();
        for (int s = nth >> 1; s > 0; s >>= 1) {
            if (threadIdx.x < s) {
                if (tv[threadIdx.x + s] > tv[threadIdx.x]) {
                    tv[threadIdx.x] = tv[threadIdx.x + s];
                    tp[threadIdx.x] = tp[threadIdx.x + s];
                }
            }
            __syncthreads();
        }
        if (threadIdx.x == 0) {
            ov[r] = tv[0];
            oi[r] = (IdxT)si[tp[0]];
            sv[tp[0]] = -INFINITY;
        }
        __syncthreads();
    }
}

std::vector<torch::Tensor> topk_cuda(torch::Tensor x, int64_t k_, int64_t S_) {
    TORCH_CHECK(x.dtype() == torch::kFloat32 && x.dim() == 2);
    auto xc = x.contiguous();
    int batch = (int)xc.size(0);
    int n = (int)xc.size(1);
    int k = (int)k_;
    int S = (int)S_;

    auto outv = torch::empty({batch, k}, xc.options());
    auto outi = torch::empty({batch, k}, xc.options().dtype(torch::kInt64));
    if (k <= 0 || n == 0 || batch == 0) return {outv, outi};

    int nth = 2048 / k;
    if (nth < 32) nth = 32;
    if (nth > 128) nth = 128;
    nth = (nth / 32) * 32;

    int C1 = nth * k;  // candidates per K1 block (<= 2048)
    auto gval1 = torch::empty({(int64_t)batch * S * C1}, xc.options());
    auto gidx1 = torch::empty({(int64_t)batch * S * C1}, xc.options().dtype(torch::kInt32));
    auto gval2 = torch::empty({(int64_t)batch * S * k}, xc.options());
    auto gidx2 = torch::empty({(int64_t)batch * S * k}, xc.options().dtype(torch::kInt32));

    long long seglen = ((long long)n + S - 1) / S;
    auto stream = at::cuda::getCurrentCUDAStream();

    seg_topk_kernel<<<batch * S, nth, 0, stream>>>(
        xc.data_ptr<float>(), gval1.data_ptr<float>(), gidx1.data_ptr<int>(),
        n, k, S, (int)seglen);
    merge_groups_kernel<<<batch * S, 128, (size_t)C1 * 8 + 1024, stream>>>(
        gval1.data_ptr<float>(), gidx1.data_ptr<int>(),
        gval2.data_ptr<float>(), gidx2.data_ptr<int>(), k, nth);
    merge_groups_kernel<int64_t><<<batch, 128, (size_t)S * k * 8 + 1024, stream>>>(
        gval2.data_ptr<float>(), gidx2.data_ptr<int>(),
        outv.data_ptr<float>(), outi.data_ptr<int64_t>(), k, S);
    return {outv, outi};
}
"""

_CPP_SRC = r"""
#include <torch/extension.h>
std::vector<torch::Tensor> topk_cuda(torch::Tensor x, int64_t k, int64_t S);
"""

_ext = load_inline(
    name="topk_ext_v3",
    cpp_sources=_CPP_SRC,
    cuda_sources=_CUDA_SRC,
    functions=["topk_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class Model(nn.Module):
    """Top-k over the last dim of a 2D fp32 tensor (custom CUDA kernel)."""

    def __init__(self, batch: int, n: int, k: int):
        super().__init__()
        self.batch, self.n, self.k = batch, n, k
        self.register_buffer("_dummy", torch.zeros(1))

    def forward(self, x: torch.Tensor):
        k = self.k
        nth = 2048 // k
        nth = max(32, min(128, nth))
        nth = (nth // 32) * 32
        # splits per row: ~1024 K1 blocks, but keep S*k <= 4096 for K3 smem
        s_cap = max(1, 4096 // k)
        s_max = max(1, x.size(1) // nth)
        s = max(1, min(s_max, s_cap, (1023 + self.batch) // self.batch))
        values, indices = _ext.topk_cuda(x, k, s)
        return values, indices


# Module-level shims rebuilt by check.py / benchmark.py per shape.
batch = 64
n = 8192
k = 8


def get_inputs():
    x = torch.randn(batch, n, dtype=torch.float32)
    return [x]


def get_init_inputs():
    return [batch, n, k]
